package worker_registry
import("context";"os";"path/filepath";"testing";"time";"strings";batchv1 "k8s.io/api/batch/v1";corev1 "k8s.io/api/core/v1";metav1 "k8s.io/apimachinery/pkg/apis/meta/v1";"google.golang.org/protobuf/proto";"google.golang.org/protobuf/types/known/timestamppb";contracts "sdo.dev/operator/contracts/gen/sdodev/contracts/v1alpha1")
func TestRWSWarmContinuationCreatesColdJob(t *testing.T){for _,restart:=range []bool{false,true}{t.Run(map[bool]string{false:"same",true:"restart"}[restart],func(t *testing.T){p,e,task:=standbyFixture(t);readyStandby(t,p);bound,err:=p.TryBind(context.Background(),e,task);if err!=nil{t.Fatal(err)};if err:=bound.publishWarmTask(context.Background(),task);err!=nil{t.Fatal(err)};file:=filepath.Join(e.RepositoryMountPath,"session/startup/initial");os.WriteFile(file,[]byte("initial"),0600);if restart{bound,err=p.TryBind(context.Background(),e,task);if err!=nil{t.Fatal(err)}};next:=proto.Clone(task).(*contracts.AgentTask);next.TaskId+="-continue-1";ctx,cancel:=context.WithTimeout(context.Background(),40*time.Millisecond);defer cancel();bound.Execute(ctx,next);name,_:=e.taskJobName(context.Background(),next);if _,err:=e.Client.BatchV1().Jobs(e.Namespace).Get(context.Background(),name,metav1.GetOptions{});err!=nil{t.Fatalf("continuation Job missing: %v",err)};if got,_:=os.ReadFile(file);string(got)!="initial"{t.Fatal("initial clock lost")}})}}
func TestRWSLateFindingsHasNoWritableAlias(t *testing.T){p,e,_:=standbyFixture(t);slot:=readyStandby(t,p);job,_:=e.Client.BatchV1().Jobs(e.Namespace).Get(context.Background(),slot.JobName,metav1.GetOptions{});for _,target:=range []string{"/sdo/late-findings/report.json","/sdo/session/late-findings/report.json"}{var selected corev1.VolumeMount;for _,m:=range job.Spec.Template.Spec.Containers[0].VolumeMounts{if strings.HasPrefix(target,m.MountPath+"/")&&len(m.MountPath)>len(selected.MountPath){selected=m}};if !selected.ReadOnly{t.Errorf("writable alias %s",target)}}}
func TestRWSUnpublishedExpiredClaimFallsBack(t *testing.T){p,e,task:=standbyFixture(t);slot:=readyStandby(t,p);bound,err:=p.TryBind(context.Background(),e,task);if err!=nil{t.Fatal(err)};job,_:=e.Client.BatchV1().Jobs(e.Namespace).Get(context.Background(),slot.JobName,metav1.GetOptions{});job.Status.Conditions=[]batchv1.JobCondition{{Type:batchv1.JobFailed,Status:corev1.ConditionTrue}};e.Client.BatchV1().Jobs(e.Namespace).UpdateStatus(context.Background(),job,metav1.UpdateOptions{});ctx,cancel:=context.WithTimeout(context.Background(),40*time.Millisecond);defer cancel();bound.Execute(ctx,task);if _,err:=os.Stat(filepath.Join(slot.Directory,"control",TaskDataKey));!os.IsNotExist(err){t.Fatal("published to dead worker")};name,_:=e.taskJobName(context.Background(),task);if name==slot.JobName{t.Fatal("dead claim retained")};if _,err:=e.Client.BatchV1().Jobs(e.Namespace).Get(context.Background(),name,metav1.GetOptions{});err!=nil{t.Fatal("cold Job missing",err)}}
func TestRWSReservationHeartbeatSurvivesBeforePublication(t *testing.T){p,e,task:=standbyFixture(t);slot:=readyStandby(t,p);ctx,cancel:=context.WithCancel(context.Background());defer cancel();_,err:=p.TryBind(ctx,e,task);if err!=nil{t.Fatal(err)};file:=filepath.Join(slot.Directory,"control/owner-heartbeat");old:=time.Now().Add(-time.Minute);os.Chtimes(file,old,old);time.Sleep(1200*time.Millisecond);info,_:=os.Stat(file);if time.Since(info.ModTime())>2*time.Second{t.Fatal("unpublished reservation lost lease")}}
func TestRWSAgingStandbyReplacedAndCannotClaim(t *testing.T){for _,ensure:=range []bool{false,true}{t.Run(map[bool]string{false:"claim",true:"replenish"}[ensure],func(t *testing.T){p,e,task:=standbyFixture(t);slot:=readyStandby(t,p);job,_:=e.Client.BatchV1().Jobs(e.Namespace).Get(context.Background(),slot.JobName,metav1.GetOptions{});job.Status.StartTime=&metav1.Time{Time:time.Now().Add(-24*time.Hour+10*time.Second)};e.Client.BatchV1().Jobs(e.Namespace).UpdateStatus(context.Background(),job,metav1.UpdateOptions{});task.Deadline=timestamppb.New(time.Now().Add(5*time.Minute));if ensure{if err:=p.Ensure(context.Background());err!=nil{t.Fatal(err)};if p.current.JobName==slot.JobName{t.Fatal("aging idle retained")}}else{bound,err:=p.TryBind(context.Background(),e,task);if err!=nil{t.Fatal(err)};if bound.WarmBinding!=nil{t.Fatal("almost expired Job claimed")}}})}}
